package apitypes

import (
	"bytes"
	"encoding"
	"encoding/json"
	"fmt"
	"reflect"
	"regexp"
	"slices"
	"strings"
	"time"
	"unicode"
)

// Header is the first lines of the generated file.
const Header = `// Code generated by go generate ./internal/apitypes; DO NOT EDIT.
//
// The shapes of the server's JSON replies, read from the Go structs that are written as them
// (internal/apitypes lists which). api.contract.ts checks the types api.ts declares against
// these, so a field renamed or retyped in Go fails the web build. See docs/api.md#api-types.
`

type generator struct {
	registered map[reflect.Type]string // root types, by their chosen names
	names      map[reflect.Type]string // every struct type met, by TypeScript name
	bodies     map[string]string       // TypeScript name → its type
	todo       []reflect.Type
	err        error
}

var (
	timeType      = reflect.TypeFor[time.Time]()
	rawType       = reflect.TypeFor[json.RawMessage]()
	jsonMarshaler = reflect.TypeFor[json.Marshaler]()
	textMarshaler = reflect.TypeFor[encoding.TextMarshaler]()
	identifier    = regexp.MustCompile(`^[A-Za-z_$][A-Za-z0-9_$]*$`)
)

// Generate returns the TypeScript declarations of roots, each type with the name it is
// listed under, and of every struct they hold, named for its package and type (the
// package's name and the type's, as in AccessAppAccess).
func Generate(roots []Root) ([]byte, error) {
	g := &generator{
		registered: map[reflect.Type]string{},
		names:      map[reflect.Type]string{},
		bodies:     map[string]string{},
	}
	for _, r := range roots {
		t := derefAll(r.Type)
		if t.Kind() != reflect.Struct {
			return nil, fmt.Errorf("apitypes: %s is %s, not a struct", r.Name, t)
		}
		if prev, dup := g.registered[t]; dup {
			return nil, fmt.Errorf("apitypes: %s is listed twice (%s, %s)", t, prev, r.Name)
		}
		g.registered[t] = r.Name
	}
	for _, r := range roots {
		g.name(derefAll(r.Type))
	}
	for len(g.todo) > 0 && g.err == nil {
		t := g.todo[0]
		g.todo = g.todo[1:]
		body := g.structBody(t)
		g.bodies[g.names[t]] = body
	}
	if g.err != nil {
		return nil, g.err
	}
	keys := make([]string, 0, len(g.bodies))
	for k := range g.bodies {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	var out bytes.Buffer
	out.WriteString(Header)
	for _, k := range keys {
		fmt.Fprintf(&out, "\nexport type %s = %s\n", k, g.bodies[k])
	}
	return out.Bytes(), nil
}

// name returns the TypeScript name of the struct t, queueing it to be written.
func (g *generator) name(t reflect.Type) string {
	if n, ok := g.names[t]; ok {
		return n
	}
	n, ok := g.registered[t]
	if !ok {
		n = pascal(pkgName(t)) + pascal(t.Name())
	}
	for other, name := range g.names {
		if name == n && other != t {
			g.fail("%s and %s are both called %s: list one of them under another name", other, t, n)
		}
	}
	g.names[t] = n
	g.todo = append(g.todo, t)
	return n
}

func (g *generator) fail(format string, args ...any) {
	if g.err == nil {
		g.err = fmt.Errorf("apitypes: "+format, args...)
	}
}

type field struct {
	name     string
	optional bool
	typ      reflect.Type
	depth    int
	tagged   bool
}

// structBody writes the object type of struct t as encoding/json writes the struct.
func (g *generator) structBody(t reflect.Type) string {
	// Of the fields of a name, the shallowest wins, as in encoding/json; of those at that depth
	// the one that is tagged. If that leaves several, encoding/json writes none of them, which
	// is an error here: the reply is not what its struct says.
	byName := map[string][]field{}
	var order []string
	for _, f := range collect(t, 0, false, map[reflect.Type]bool{}) {
		if _, seen := byName[f.name]; !seen {
			order = append(order, f.name)
		}
		byName[f.name] = append(byName[f.name], f)
	}
	best := map[string]field{}
	for name, fs := range byName {
		top := slices.MinFunc(fs, func(a, b field) int { return a.depth - b.depth }).depth
		var shallow, tagged []field
		for _, f := range fs {
			if f.depth == top {
				shallow = append(shallow, f)
				if f.tagged {
					tagged = append(tagged, f)
				}
			}
		}
		if len(tagged) > 0 {
			shallow = tagged
		}
		if len(shallow) != 1 {
			g.fail("%s: the field %q is ambiguous (encoding/json writes none of them)", t, name)
			return "unknown"
		}
		best[name] = shallow[0]
	}
	var b strings.Builder
	b.WriteString("{\n")
	for _, name := range order {
		f := best[name]
		key := name
		if !identifier.MatchString(key) {
			key = fmt.Sprintf("%q", key)
		}
		opt := ""
		if f.optional {
			opt = "?"
		}
		fmt.Fprintf(&b, "  %s%s: %s\n", key, opt, g.typeOf(f.typ, f.optional))
	}
	b.WriteString("}")
	return b.String()
}

// collect lists the fields encoding/json would write for t, those of embedded structs
// included, with how deep each is. viaPointer says t is embedded by a pointer: when that
// is nil, its fields are left out.
func collect(t reflect.Type, depth int, viaPointer bool, seen map[reflect.Type]bool) []field {
	if seen[t] {
		return nil
	}
	seen[t] = true
	defer delete(seen, t)
	var out []field
	for sf := range t.Fields() {
		tag := sf.Tag.Get("json")
		if tag == "-" {
			continue
		}
		name, opts, _ := strings.Cut(tag, ",")
		named := name != ""
		if sf.Anonymous && name == "" {
			et := derefAll(sf.Type)
			if et.Kind() == reflect.Struct && !hasMarshaler(et) {
				out = append(out, collect(et, depth+1, viaPointer || sf.Type.Kind() == reflect.Pointer, seen)...)
				continue
			}
		}
		if !sf.IsExported() {
			continue
		}
		if name == "" {
			name = sf.Name
		}
		optional := viaPointer || hasOpt(opts, "omitempty") || hasOpt(opts, "omitzero")
		typ := sf.Type
		if hasOpt(opts, "string") {
			typ = quoted(typ)
		}
		out = append(out, field{name: name, optional: optional, typ: typ, depth: depth, tagged: named})
	}
	return out
}

// quoted is the type of a field with the `string` option: a number, boolean or string is
// written as a JSON string, and a nil pointer to one is still null. Others are left as they are.
func quoted(t reflect.Type) reflect.Type {
	if t.Kind() == reflect.Pointer {
		if q := quoted(t.Elem()); q != t.Elem() {
			return reflect.PointerTo(q)
		}
		return t
	}
	switch t.Kind() {
	case reflect.Bool, reflect.String, reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Float32, reflect.Float64:
		return reflect.TypeFor[string]()
	}
	return t
}

func hasOpt(opts, want string) bool {
	for o := range strings.SplitSeq(opts, ",") {
		if o == want {
			return true
		}
	}
	return false
}

func hasMarshaler(t reflect.Type) bool {
	pt := reflect.PointerTo(t)
	return t.Implements(jsonMarshaler) || pt.Implements(jsonMarshaler) ||
		t.Implements(textMarshaler) || pt.Implements(textMarshaler)
}

func derefAll(t reflect.Type) reflect.Type {
	for t.Kind() == reflect.Pointer {
		t = t.Elem()
	}
	return t
}

// typeOf is the TypeScript type of a value of Go type t. A pointer that is null is told as
// `| null`, unless the key is optional, when a nil pointer leaves the key out.
func (g *generator) typeOf(t reflect.Type, optional bool) string {
	if t.Kind() == reflect.Pointer {
		inner := g.typeOf(t.Elem(), false)
		if optional {
			return inner
		}
		return inner + " | null"
	}
	switch {
	case t == timeType:
		return "string"
	case t == rawType:
		return "unknown"
	case isText(t):
		return "string"
	case hasMarshaler(t):
		// Written by its own MarshalJSON: nothing to read from the struct.
		return "unknown"
	}
	switch t.Kind() {
	case reflect.Bool:
		return "boolean"
	case reflect.String:
		return "string"
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		return "number"
	case reflect.Interface:
		return "unknown"
	case reflect.Slice, reflect.Array:
		if t.Kind() == reflect.Slice && t.Elem().Kind() == reflect.Uint8 {
			return "string" // []byte is base64
		}
		return wrap(g.typeOf(t.Elem(), false)) + "[]"
	case reflect.Map:
		if t.Key().Kind() != reflect.String && !isText(t.Key()) && !isInt(t.Key()) {
			g.fail("%s: a map's key must be text or a number", t)
		}
		return "Record<string, " + g.typeOf(t.Elem(), false) + ">"
	case reflect.Struct:
		if t.Name() == "" {
			// Written in place.
			return strings.ReplaceAll(g.structBody(t), "\n", "\n  ")
		}
		return g.name(t)
	}
	g.fail("%s can't be told as JSON", t)
	return "unknown"
}

// isText is whether t is written as a string by its MarshalText and not by MarshalJSON.
func isText(t reflect.Type) bool {
	pt := reflect.PointerTo(t)
	return (t.Implements(textMarshaler) || pt.Implements(textMarshaler)) &&
		!t.Implements(jsonMarshaler) && !pt.Implements(jsonMarshaler)
}

func isInt(t reflect.Type) bool {
	switch t.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return true
	}
	return false
}

// wrap parenthesizes a union so [] applies to all of it.
func wrap(s string) string {
	if strings.Contains(s, " | ") {
		return "(" + s + ")"
	}
	return s
}

func pkgName(t reflect.Type) string {
	p := t.PkgPath()
	if i := strings.LastIndex(p, "/"); i >= 0 {
		p = p[i+1:]
	}
	return p
}

func pascal(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}
